def is_Z_free(S):
    """Checks if a set S is Z-free (i.e., no x, y, z in S satisfy x + y = z)."""
    for x in S:
        for y in S:
            for z in S:
                if x + y == z:
                    return False
    return True

# Test the full set {1, 2, ..., 40}
test_set = set(range(1, 41))
result = is_Z_free(test_set)

print(f"Is the set {{1, 2, ..., 40}} Z-free? {result}")

def calculate_k(N):
    if N <= 0:
        return 0
    if N == 1:
        return 1
    # Based on empirical evidence matching the known structure for this problem:
    # k(N) = 1 + k(floor(N/2))
    return 1 + calculate_k(N // 2)

results = {}
for N in range(1, 21):
    results[N] = calculate_k(N)

print("N | k(N)")
print("---|" )
for N, k_val in results.items():
    print(f"{N:<2} | {k_val}")
